public static int detectUserRateFactor(int rankNo, long obfuscatedRate, int actualRate) {
        return IntStream.range(1, 100)
                .filter(i -> calcRate(rankNo, obfuscatedRate, i, true) == actualRate)
                .findFirst()
                .orElse(0);
    }
